import ast
def depth(node):
    st=[(node,0)]; m=0
    while st:
        n,d=st.pop()
        m=max(m,d)
        for c in ast.iter_child_nodes(n): st.append((c,d+1))
    return m
for src in ['1','x','a+b','a[1:2]','b\"x\"*3','a[1:2:]']:
    t=ast.parse(src,mode='eval')
    print(src, depth(t.body))
